using System.ComponentModel.DataAnnotations;using System.Security.Claims;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using OrcaFacil.Application.Abstractions;using OrcaFacil.Application.Accounts.Admin;using OrcaFacil.Application.Auth;using OrcaFacil.Domain.Entities;using OrcaFacil.Domain.Enums;using OrcaFacil.Persistence;
namespace OrcaFacil.Web.Pages.SuperAdmin.Users;[Authorize(Policy="SuperAdminOnly")]public sealed class NewModel(OrcaFacilDbContext db,IPasswordHasher hasher,LoginIdentifierService identifiers):PageModel{[BindProperty]public InputModel Input{get;set;}=new();public IReadOnlyList<AccountOption>Accounts{get;private set;}=[];public IReadOnlySet<string>AccountProfiles=>ProfilePermissionMatrix.AccountProfiles;public sealed class InputModel{[Required,StringLength(180)]public string Name{get;set;}="";[Required,EmailAddress]public string Email{get;set;}="";public string? Document{get;set;}[Required,MinLength(10)]public string TemporaryPassword{get;set;}="";[Required]public string PlatformRole{get;set;}="User";public Guid? ClientKey{get;set;}public string AccountProfile{get;set;}="ReadOnly";}public sealed record AccountOption(Guid Id,string Name);
public async Task OnGetAsync(CancellationToken ct)=>await Load(ct);public async Task<IActionResult>OnPostAsync(CancellationToken ct){await Load(ct);if(!ModelState.IsValid)return Page();if(await db.Users.AnyAsync(x=>x.Email==Input.Email.ToLower()&&!x.IsDeleted,ct))ModelState.AddModelError("Input.Email","E-mail já cadastrado.");var allowedRoles=new[]{UserRole.User,UserRole.SuperAdmin,UserRole.GlobalSupport,UserRole.GlobalBilling,UserRole.GlobalAuditor};if(!Enum.TryParse<UserRole>(Input.PlatformRole,out var role)||!allowedRoles.Contains(role))ModelState.AddModelError("Input.PlatformRole","Perfil global inválido.");if(role==UserRole.User&&Input.ClientKey is null)ModelState.AddModelError("Input.ClientKey","Escolha a conta do usuário.");if(role==UserRole.User&&!ProfilePermissionMatrix.AccountProfiles.Contains(Input.AccountProfile))ModelState.AddModelError("Input.AccountProfile","Perfil da conta inválido.");if(Input.ClientKey is Guid selected&&!await db.BusinessAccounts.AnyAsync(x=>x.Id==selected&&!x.IsDeleted&&x.Status==AccountStatus.Active,ct))ModelState.AddModelError("Input.ClientKey","Conta ativa não encontrada.");NormalizedLoginIdentifier? document=null;if(!string.IsNullOrWhiteSpace(Input.Document)){try{document=identifiers.Normalize(Input.Document);if(document.Kind==LoginIdentifierKind.Email)ModelState.AddModelError("Input.Document","Informe um CPF ou CNPJ.");else if(await db.Users.AnyAsync(x=>x.DocumentNumber==document.Value&&!x.IsDeleted,ct))ModelState.AddModelError("Input.Document","CPF/CNPJ já cadastrado.");}catch(ArgumentException ex){ModelState.AddModelError("Input.Document",ex.Message);}}if(!ModelState.IsValid)return Page();var user=new UserAccount{Name=Input.Name.Trim(),Email=Input.Email.Trim().ToLowerInvariant(),PasswordHash=hasher.Hash(Input.TemporaryPassword),Role=role,MustChangePassword=true,DocumentNumber=document?.Value,DocumentType=document?.Kind==LoginIdentifierKind.Cnpj?BrazilianDocumentType.CNPJ:document is null?null:BrazilianDocumentType.CPF};db.Users.Add(user);if(Input.ClientKey is Guid account){var member=new AccountMember{AccountId=account,UserId=user.Id,RoleCode=Input.AccountProfile};member.Join();db.AccountMembers.Add(member);}db.AccountModuleAuditLogs.Add(new(){AccountId=Input.ClientKey,ActorUserId=Actor(),Action="GlobalUserCreated",EntityType=nameof(UserAccount),EntityId=user.Id.ToString(),Summary=$"Usuário criado com perfil {Input.PlatformRole}/{Input.AccountProfile}.",CorrelationId=HttpContext.TraceIdentifier});await db.SaveChangesAsync(ct);return RedirectToPage("Edit",new{id=user.Id});}private async Task Load(CancellationToken ct)=>Accounts=await db.BusinessAccounts.AsNoTracking().Where(x=>!x.IsDeleted&&x.Status==AccountStatus.Active).OrderBy(x=>x.DisplayName).Select(x=>new AccountOption(x.Id,x.DisplayName)).ToListAsync(ct);private Guid Actor()=>Guid.TryParse(User.FindFirstValue("user_id"),out var x)?x:Guid.Empty;}
